# Generated by deployify. Do not edit manually; 'deployify generate' rewrites it.
#
# Drives the Windows service manager for Deployify's host target. Deployify runs it locally
# with -Action and writes the request (JSON) to standard input; secrets and the connection
# password travel that way, never on the command line or in a file. The script opens a
# PowerShell remoting session to the host (WinRM or SSH) or, with no host, works on this
# machine, and prints one result line:
#   ##deployify {json}
#
# Layout on the host, under the root (host.root, C:\deployify by default):
#   {name}\deployify.json              ownership marker: service, environment, release, ...
#   {name}\releases\{release}\app\     the published app; the Windows service runs its .exe
#   {name}\settings\{release}.json     that release's variables, secrets included (Administrators only)
#
# The service's environment variables live in its registry key, which is closed to everyone
# but Administrators and SYSTEM.
#
# Compatible with Windows PowerShell 5.1 and PowerShell 7.

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Ping', 'List', 'Apply', 'Activate', 'Health', 'Delete', 'Logs')]
    [string]$Action
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

# ---------------------------------------------------------------------------------------------
# Runs on the host, in the remoting session or locally. Returns '##result {json}'.
# ---------------------------------------------------------------------------------------------
$server = {
    param([string]$ServerAction, [string]$RequestJson)

    $ErrorActionPreference = 'Stop'
    $ProgressPreference = 'SilentlyContinue'
    $request = $RequestJson | ConvertFrom-Json
    $root = $request.root
    $markerName = 'deployify.json'

    function Out-Result($value) {
        return '##result ' + (ConvertTo-Json -InputObject $value -Depth 10 -Compress)
    }

    function Read-Marker([string]$dir) {
        $path = Join-Path $dir $markerName
        if (Test-Path $path) { return (Get-Content -Raw -Path $path | ConvertFrom-Json) }
        return $null
    }

    function Get-ReleasePath([string]$serviceDir, [string]$release) {
        return Join-Path (Join-Path $serviceDir 'releases') $release
    }

    function Get-Win32Service([string]$name) {
        return Get-CimInstance -ClassName Win32_Service -Filter "Name='$name'"
    }

    function Assert-Change($result, [string]$what) {
        if ($result.ReturnValue -ne 0) { throw "Changing the $what of service failed (Win32_Service.Change returned $($result.ReturnValue))." }
    }

    function Test-Administrator {
        $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
        return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }

    # Closes a service's registry key, where its variables live, to everyone but Administrators and SYSTEM.
    function Protect-ServiceKey([string]$key) {
        $acl = Get-Acl -Path $key
        if ($acl.AreAccessRulesProtected) { return }
        $acl.SetAccessRuleProtection($true, $false)
        foreach ($rule in @($acl.Access)) { [void]$acl.RemoveAccessRule($rule) }
        foreach ($sid in 'S-1-5-32-544', 'S-1-5-18') {
            $acl.AddAccessRule((New-Object System.Security.AccessControl.RegistryAccessRule(
                (New-Object System.Security.Principal.SecurityIdentifier($sid)), 'FullControl', 'ContainerInherit', 'None', 'Allow')))
        }
        Set-Acl -Path $key -AclObject $acl
    }

    # UseWindowsService() logs to the Application log under the app's name; the account the
    # service runs as can't register that source, so the deploy does.
    function Register-EventSource([string]$source) {
        try {
            if (-not [System.Diagnostics.EventLog]::SourceExists($source)) {
                [System.Diagnostics.EventLog]::CreateEventSource($source, 'Application')
            }
        } catch { }
    }

    # Readable by Administrators and SYSTEM only.
    function New-PrivateFolder([string]$dir) {
        if (Test-Path $dir) { return }
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
        $acl = New-Object System.Security.AccessControl.DirectorySecurity
        $acl.SetAccessRuleProtection($true, $false)
        foreach ($sid in 'S-1-5-32-544', 'S-1-5-18') {
            $rule = New-Object System.Security.AccessControl.FileSystemAccessRule(
                (New-Object System.Security.Principal.SecurityIdentifier($sid)), 'FullControl',
                'ContainerInherit, ObjectInherit', 'None', 'Allow')
            $acl.AddAccessRule($rule)
        }
        Set-Acl -Path $dir -AclObject $acl
    }

    function Save-Settings([string]$serviceDir, $svc, $variables) {
        $dir = Join-Path $serviceDir 'settings'
        New-PrivateFolder $dir
        $saved = [pscustomobject]@{ service = $svc; variables = $variables }
        ConvertTo-Json -InputObject $saved -Depth 20 | Set-Content -Path (Join-Path $dir "$($svc.release).json") -Encoding UTF8
    }

    function Read-Settings([string]$serviceDir, [string]$release) {
        $path = Join-Path (Join-Path $serviceDir 'settings') "$release.json"
        if (-not (Test-Path $path)) { return $null }
        return (Get-Content -Raw -Path $path | ConvertFrom-Json)
    }

    # Records what runs now, and the release that ran before it, which pruning keeps for a rollback.
    function Write-Marker([string]$serviceDir, $svc, $processId) {
        $old = Read-Marker $serviceDir
        $previous = $null
        if ($null -ne $old) {
            $previous = $old.release
            if ($previous -eq $svc.release) { $previous = $old.previous }
        }
        [pscustomobject]@{
            managedBy   = 'deployify'
            service     = $svc.service
            environment = $svc.environment
            name        = $svc.name
            unitName    = $svc.unitName
            fingerprint = $svc.fingerprint
            release     = $svc.release
            previous    = $previous
            entryPoint  = $svc.entryPoint
            processId   = $processId
            deployedAt  = (Get-Date).ToUniversalTime().ToString('o')
        } | ConvertTo-Json | Set-Content -Path (Join-Path $serviceDir $markerName) -Encoding UTF8
    }

    # Creates or updates the Windows service so it runs the release's executable as the
    # configured account with the release's variables, then (re)starts it. Returns its process ID.
    function Set-Service-Release($svc, $variables, [string]$releasePath, [string]$account, [string]$password) {
        $exe = Join-Path (Join-Path $releasePath 'app') "$($svc.entryPoint).exe"
        if (-not (Test-Path $exe)) { throw "$($svc.entryPoint).exe is not in the package for $($svc.service); publish for a Windows runtime (win-x64)." }
        $binPath = '"' + $exe + '"'
        $name = $svc.unitName
        $display = "$($svc.service) ($($svc.environment), Deployify)"

        $existing = Get-Win32Service $name
        if ($null -eq $existing) {
            New-Service -Name $name -BinaryPathName $binPath -DisplayName $display -StartupType Automatic | Out-Null
            $existing = Get-Win32Service $name
        } else {
            Assert-Change (Invoke-CimMethod -InputObject $existing -MethodName Change -Arguments @{ PathName = $binPath; DisplayName = $display }) 'path'
        }

        $startName = $account
        if ($account -eq 'LocalSystem' -or $account -eq 'NT AUTHORITY\SYSTEM') { $startName = 'LocalSystem' }
        $secret = ''
        if ($password) { $secret = [string]$password }
        Assert-Change (Invoke-CimMethod -InputObject $existing -MethodName Change -Arguments @{ StartName = $startName; StartPassword = $secret }) 'account'

        # Restart after a crash, like systemd's Restart=on-failure; the health gate notices the new process.
        & sc.exe failure $name reset= 86400 actions= restart/5000/restart/5000/restart/5000 | Out-Null

        # Variables in the service's registry key, closed to everyone but Administrators and SYSTEM.
        $key = "HKLM:\SYSTEM\CurrentControlSet\Services\$name"
        $entries = @()
        foreach ($p in $variables.PSObject.Properties) { $entries += "$($p.Name)=$($p.Value)" }
        Protect-ServiceKey $key
        if ($entries.Count -gt 0) {
            New-ItemProperty -Path $key -Name 'Environment' -PropertyType MultiString -Value ([string[]]$entries) -Force | Out-Null
        } else {
            Remove-ItemProperty -Path $key -Name 'Environment' -ErrorAction SilentlyContinue
        }

        Register-EventSource $svc.entryPoint

        $service = Get-Service -Name $name
        if ($service.Status -ne 'Stopped') {
            Stop-Service -Name $name -Force
            $service.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
        }
        try {
            Start-Service -Name $name
        } catch {
            throw "$name did not start: $($_.Exception.Message) A .NET app only runs as a Windows service when it calls UseWindowsService() (package Microsoft.Extensions.Hosting.WindowsServices); see 'deployify logs $($svc.service)'."
        }
        return (Get-Win32Service $name).ProcessId
    }

    # Keeps the newest releases and their settings; one still locked goes next time. The current
    # release and the one that ran before it always stay, so a rollback can go back to it.
    function Remove-OldReleases([string]$serviceDir, [string]$current, [int]$keep) {
        $previous = $null
        $marker = Read-Marker $serviceDir
        if ($null -ne $marker) { $previous = $marker.previous }
        if ($previous -and $previous -ne $current) { $keep = $keep - 1 }
        Get-ChildItem -Path (Join-Path $serviceDir 'releases') -Directory |
            Where-Object { $_.Name -ne $current -and $_.Name -ne $previous } |
            Sort-Object CreationTimeUtc -Descending |
            Select-Object -Skip ([Math]::Max(0, $keep - 1)) |
            ForEach-Object { try { Remove-Item -Path $_.FullName -Recurse -Force } catch { } }
        $settingsDir = Join-Path $serviceDir 'settings'
        if (Test-Path $settingsDir) {
            Get-ChildItem -Path $settingsDir -Filter '*.json' |
                Where-Object { -not (Test-Path (Get-ReleasePath $serviceDir $_.BaseName)) } |
                ForEach-Object { try { Remove-Item -Path $_.FullName -Force } catch { } }
        }
    }

    # One HTTP request on this host; returns the status code (null when no response).
    function Get-HttpStatus([string]$url) {
        $request = [System.Net.WebRequest]::Create($url)
        $request.Timeout = 10000
        $request.AllowAutoRedirect = $false
        $response = $null
        try {
            $response = $request.GetResponse()
        } catch {
            $ex = $_.Exception
            while ($null -ne $ex -and -not ($ex -is [System.Net.WebException])) { $ex = $ex.InnerException }
            if ($null -eq $ex -or $null -eq $ex.Response) {
                $message = $_.Exception.Message
                if ($null -ne $ex) { $message = $ex.Message }
                return [pscustomobject]@{ code = $null; error = $message }
            }
            $response = $ex.Response
        }
        try { return [pscustomobject]@{ code = [int]$response.StatusCode; error = $null } }
        finally { $response.Close() }
    }

    switch ($ServerAction) {
        'Ping' {
            $windows = [Environment]::OSVersion.Platform -eq 'Win32NT'
            $admin = $false
            if ($windows) { $admin = Test-Administrator }
            return Out-Result ([pscustomobject]@{
                computer = $env:COMPUTERNAME
                windows  = $windows
                admin    = $admin
            })
        }

        'List' {
            $services = @()
            if (Test-Path $root) {
                foreach ($dir in Get-ChildItem -Path $root -Directory) {
                    $marker = Read-Marker $dir.FullName
                    if ($null -eq $marker -or $marker.managedBy -ne 'deployify') { continue }
                    $services += [pscustomobject]@{
                        service     = $marker.service
                        environment = $marker.environment
                        name        = $marker.name
                        unitName    = $marker.unitName
                        fingerprint = $marker.fingerprint
                        release     = $marker.release
                        installed   = ($null -ne (Get-Service -Name $marker.unitName -ErrorAction SilentlyContinue))
                    }
                }
            }
            return Out-Result ([pscustomobject]@{ services = $services })
        }

        'Prepare' {
            # Makes an empty release folder for the package, unless it is complete already.
            $svc = $request.service
            $serviceDir = Join-Path $root $svc.name
            if ((Test-Path $serviceDir) -and $null -eq (Read-Marker $serviceDir) -and
                @(Get-ChildItem -Path $serviceDir | Where-Object { $_.Name -ne 'releases' }).Count -gt 0) {
                throw "$serviceDir on $env:COMPUTERNAME already exists and was not deployed by Deployify; remove it or set host.namePrefix."
            }
            if ($null -eq (Read-Marker $serviceDir) -and $null -ne (Get-Service -Name $svc.unitName -ErrorAction SilentlyContinue)) {
                throw "Windows service '$($svc.unitName)' already exists on $env:COMPUTERNAME and was not installed by Deployify."
            }
            $release = Get-ReleasePath $serviceDir $svc.release
            $app = Join-Path $release 'app'
            if (Test-Path (Join-Path $release '.complete')) {
                return Out-Result ([pscustomobject]@{ appPath = $app; needsCopy = $false })
            }
            if (Test-Path $release) { Remove-Item -Path $release -Recurse -Force }
            New-Item -ItemType Directory -Force -Path $app | Out-Null
            return Out-Result ([pscustomobject]@{ appPath = $app; needsCopy = $true })
        }

        'Apply' {
            $svc = $request.service
            $serviceDir = Join-Path $root $svc.name
            $release = Get-ReleasePath $serviceDir $svc.release
            if (-not (Test-Path (Join-Path $release 'app\*'))) { throw "Release folder $release is empty; the package was not copied." }
            Set-Content -Path (Join-Path $release '.complete') -Value $svc.fingerprint

            $marker = Read-Marker $serviceDir
            $running = Get-Service -Name $svc.unitName -ErrorAction SilentlyContinue
            if ($null -ne $marker -and $marker.fingerprint -eq $svc.fingerprint -and $marker.release -eq $svc.release -and
                $null -ne $running -and $running.Status -eq 'Running') {
                Remove-OldReleases $serviceDir $svc.release ([int]$svc.keepReleases)
                return Out-Result ([pscustomobject]@{ changed = $false })
            }

            Save-Settings $serviceDir $svc $request.variables
            $processId = Set-Service-Release $svc $request.variables $release $request.account $request.accountPassword
            Write-Marker $serviceDir $svc $processId
            Remove-OldReleases $serviceDir $svc.release ([int]$svc.keepReleases)
            return Out-Result ([pscustomobject]@{ changed = $true })
        }

        'Activate' {
            # Rollback: put the service back on a release still on the host, with that release's variables.
            $serviceDir = Join-Path $root $request.name
            $marker = Read-Marker $serviceDir
            if ($null -eq $marker -or $marker.managedBy -ne 'deployify') {
                throw "'$($request.name)' was not deployed by Deployify on $env:COMPUTERNAME."
            }
            $release = Get-ReleasePath $serviceDir $request.release
            $saved = Read-Settings $serviceDir $request.release
            if (-not (Test-Path (Join-Path $release '.complete')) -or $null -eq $saved) {
                throw "Release $($request.release) of '$($request.name)' is no longer on $env:COMPUTERNAME (only the newest host.keepReleases are kept)."
            }
            $running = Get-Service -Name $marker.unitName -ErrorAction SilentlyContinue
            if ($marker.release -eq $request.release -and $null -ne $running -and $running.Status -eq 'Running') {
                return Out-Result ([pscustomobject]@{ changed = $false })
            }
            $processId = Set-Service-Release $saved.service $saved.variables $release $request.account $request.accountPassword
            Write-Marker $serviceDir $saved.service $processId
            return Out-Result ([pscustomobject]@{ changed = $true })
        }

        'Health' {
            $marker = Read-Marker (Join-Path $root $request.name)
            function Out-Health([string]$state, [string]$detail) {
                return Out-Result ([pscustomobject]@{ state = $state; detail = $detail })
            }

            if ($null -eq $marker) { return Out-Health 'failed' "'$($request.name)' is not deployed on $env:COMPUTERNAME" }
            if ($marker.release -ne $request.release) {
                return Out-Health 'failed' "$env:COMPUTERNAME runs release $($marker.release), not $($request.release)"
            }
            $svc = Get-Win32Service $request.unitName
            if ($null -eq $svc) { return Out-Health 'failed' "Windows service '$($request.unitName)' is gone from $env:COMPUTERNAME" }
            if ($svc.State -eq 'Stopped') {
                return Out-Health 'failed' "$($request.unitName) stopped on $env:COMPUTERNAME (exit code $($svc.ExitCode)); see 'deployify logs $($marker.service)'"
            }
            if ($svc.State -ne 'Running') { return Out-Health 'progressing' "$env:COMPUTERNAME`: $($svc.State)" }
            if ($null -ne $marker.processId -and [int]$marker.processId -ne 0 -and [int]$svc.ProcessId -ne [int]$marker.processId) {
                return Out-Health 'failed' "$($request.unitName) restarted on $env:COMPUTERNAME since the deploy (it crashed); see 'deployify logs $($marker.service)'"
            }

            if ($request.port) {
                $path = [string]$request.path
                $url = "http://$($request.healthHost):$($request.port)$path"
                $response = Get-HttpStatus $url
                if ($null -eq $response.code) { return Out-Health 'progressing' "no response from $url on $env:COMPUTERNAME yet ($($response.error))" }
                if ($response.code -lt 500) { return Out-Health 'healthy' "HTTP $($response.code) from $url on $env:COMPUTERNAME" }
                return Out-Health 'progressing' "HTTP $($response.code) from $url on $env:COMPUTERNAME"
            }

            $started = (Get-Process -Id $svc.ProcessId).StartTime
            $up = [int]((Get-Date) - $started).TotalSeconds
            if ($up -ge [int]$request.startup) { return Out-Health 'healthy' "running for ${up}s on $env:COMPUTERNAME" }
            return Out-Health 'progressing' "running for ${up}s on $env:COMPUTERNAME, waiting for $($request.startup)s"
        }

        'Logs' {
            # The app's entries in the Application log (UseWindowsService() writes them under the
            # app's name, warnings and errors by default) and the service manager's entries about
            # the service in the System log (crashes, failures to start). Without a cursor: the
            # last $request.tail entries; with one: what was written since.
            $serviceDir = Join-Path $root $request.name
            $marker = Read-Marker $serviceDir
            if ($null -eq $marker -or $marker.managedBy -ne 'deployify') {
                throw "'$($request.name)' is not deployed by Deployify on $env:COMPUTERNAME."
            }
            $display = "$($marker.service) ($($marker.environment), Deployify)"
            $since = $null
            if ($request.since) { $since = [DateTime]::Parse([string]$request.since, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::AdjustToUniversal) }
            $tail = 10000
            if ($null -ne $request.tail) { $tail = [Math]::Min(10000, [int]$request.tail) }
            $cursor = $request.cursor
            $out = New-Object System.Collections.Generic.List[object]
            $next = @{}

            $sources = @(
                @{ key = 'app'; log = 'Application'; provider = [string]$marker.entryPoint; instance = $null; match = $null },
                @{ key = 'scm'; log = 'System'; provider = 'Service Control Manager'; instance = 'service-manager'; match = $display }
            )
            $collected = New-Object System.Collections.Generic.List[object]
            foreach ($s in $sources) {
                $last = 0
                if ($null -ne $cursor -and $null -ne $cursor.($s.key)) { $last = [long]$cursor.($s.key) }
                $filter = @{ LogName = $s.log; ProviderName = $s.provider }
                if ($null -ne $since) { $filter.StartTime = $since.ToLocalTime() }
                $events = @()
                try { $events = @(Get-WinEvent -FilterHashtable $filter -MaxEvents 2000 -ErrorAction Stop) } catch { }
                $events = @($events | Where-Object { $_.RecordId -gt $last } | Sort-Object RecordId)
                if ($null -ne $s.match) {
                    $events = @($events | Where-Object { $null -ne $_.Message -and $_.Message.IndexOf($s.match, [StringComparison]::OrdinalIgnoreCase) -ge 0 })
                }
                if ($null -eq $cursor) { $events = @($events | Select-Object -Last $tail) }
                $nextRecord = $last
                foreach ($e in $events) {
                    $time = $e.TimeCreated.ToUniversalTime().ToString('o')
                    $message = $e.Message
                    if ($null -eq $message) { $message = '' }
                    foreach ($line in @($message -split "`r?`n" | Where-Object { $_ -ne '' })) {
                        $collected.Add([pscustomobject]@{ text = [string]$line; instance = $s.instance; time = $time; error = ($e.Level -le 2) })
                    }
                    $nextRecord = [Math]::Max($nextRecord, $e.RecordId)
                }
                if ($null -eq $cursor -and $events.Count -eq 0) {
                    try {
                        $latest = @(Get-WinEvent -FilterHashtable @{ LogName = $s.log; ProviderName = $s.provider } -MaxEvents 1 -ErrorAction Stop)
                        if ($latest.Count -gt 0) { $nextRecord = $latest[0].RecordId }
                    } catch { }
                }
                $next[$s.key] = $nextRecord
            }
            foreach ($l in @($collected | Sort-Object time)) { $out.Add($l) }

            return Out-Result ([pscustomobject]@{
                lines  = $out.ToArray()
                cursor = [pscustomobject]$next
            })
        }

        'Delete' {
            $serviceDir = Join-Path $root $request.name
            $removed = @()
            if (-not (Test-Path $serviceDir)) { return Out-Result ([pscustomobject]@{ removed = $removed }) }
            $marker = Read-Marker $serviceDir
            if ($null -eq $marker -or $marker.managedBy -ne 'deployify') {
                throw "'$($request.name)' was not deployed by Deployify on $env:COMPUTERNAME; leaving it alone."
            }
            $service = Get-Service -Name $request.unitName -ErrorAction SilentlyContinue
            if ($null -ne $service) {
                if ($service.Status -ne 'Stopped') {
                    Stop-Service -Name $request.unitName -Force
                    $service.WaitForStatus('Stopped', [TimeSpan]::FromSeconds(60))
                }
                & sc.exe delete $request.unitName | Out-Null
                $removed += "Windows service $($request.unitName)"
            }

            # The process may hold files for a moment after it stops.
            for ($i = 1; $i -le 5; $i++) {
                try { Remove-Item -Path $serviceDir -Recurse -Force; break }
                catch { if ($i -eq 5) { throw "Removed '$($request.unitName)' but not its folder $($serviceDir): $($_.Exception.Message)" }; Start-Sleep -Seconds 2 }
            }
            $removed += "folder $serviceDir"
            return Out-Result ([pscustomobject]@{ removed = $removed })
        }

        default { throw "Unknown action $ServerAction" }
    }
}

# ---------------------------------------------------------------------------------------------
# Runs where Deployify runs: opens the session and copies the package.
# ---------------------------------------------------------------------------------------------
$session = $null
try {
    $request = [Console]::In.ReadToEnd() | ConvertFrom-Json
    $connection = $request.connection
    $request.PSObject.Properties.Remove('connection')
    $packagePath = $request.packagePath
    $serverJson = ConvertTo-Json -InputObject $request -Depth 20 -Compress

    if ($connection.host) {
        $options = @{ ErrorAction = 'Stop' }
        if ($connection.transport -eq 'Ssh') {
            $options.HostName = $connection.host
            if ($connection.userName) { $options.UserName = $connection.userName }
            if ($connection.keyFilePath) { $options.KeyFilePath = $connection.keyFilePath }
            if ($connection.port) { $options.Port = [int]$connection.port }
        } else {
            $options.ComputerName = $connection.host
            if ($connection.useSsl) { $options.UseSSL = $true }
            if ($connection.port) { $options.Port = [int]$connection.port }
            if ($connection.userName) {
                if (-not $connection.password) { throw "host.userName is set but no password was found (host.password or HOST_PASSWORD)." }
                $secure = ConvertTo-SecureString -String $connection.password -AsPlainText -Force
                $options.Credential = New-Object System.Management.Automation.PSCredential($connection.userName, $secure)
            }
        }
        $session = New-PSSession @options
    }

    function Invoke-Server([string]$serverAction) {
        if ($null -ne $session) {
            $output = Invoke-Command -Session $session -ScriptBlock $server -ArgumentList $serverAction, $serverJson
        } else {
            $output = & $server $serverAction $serverJson
        }
        $line = @($output) | Where-Object { $_ -is [string] -and $_.StartsWith('##result ') } | Select-Object -Last 1
        if ($null -eq $line) { throw "The host returned no result for $serverAction." }
        return $line.Substring(9)
    }

    if ($Action -eq 'Apply') {
        $prepared = Invoke-Server 'Prepare' | ConvertFrom-Json
        if ($prepared.needsCopy) {
            $source = Join-Path $packagePath '*'
            if ($null -ne $session) {
                Copy-Item -Path $source -Destination $prepared.appPath -ToSession $session -Recurse -Force
            } else {
                Copy-Item -Path $source -Destination $prepared.appPath -Recurse -Force
            }
        }
    }

    Write-Output ('##deployify ' + (Invoke-Server $Action))
    exit 0
}
catch {
    [Console]::Error.WriteLine($_.Exception.Message)
    exit 1
}
finally {
    if ($null -ne $session) { Remove-PSSession -Session $session }
}
